"""Hook point catalogue and per-point metadata."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Type

from rasa.mantle.hooks.constants import (
    DEFAULT_MODIFY_TIMEOUT_MS,
    DEFAULT_OBSERVE_TIMEOUT_MS,
    FAIL_CLOSED,
    FAIL_OPEN,
    POINT_INCOMING_MESSAGE,
    POINT_KNOWLEDGE_QUERY,
    POINT_KNOWLEDGE_RESULTS,
    POINT_MODEL_REQUEST,
    POINT_MODEL_RESPONSE,
    POINT_OUTGOING_TEXT,
    POINT_TOOL_CALL,
    POINT_TOOL_RESULT,
    POINT_TURN_FINISHED,
    POINT_TURN_STARTED,
    modify_decorator_name,
    observe_decorator_name,
)
from rasa.mantle.hooks.exceptions import HookRejection, RetryModel
from rasa.mantle.hooks.payloads import (
    HookPayload,
    IncomingMessagePayload,
    KnowledgeQueryPayload,
    KnowledgeResultsPayload,
    ModelRequestPayload,
    ModelResponsePayload,
    OutgoingTextPayload,
    ToolCallPayload,
    ToolResultPayload,
    TurnFinishedPayload,
    TurnStartedPayload,
)
from rasa.mantle.hooks.types import (
    MODIFY_LANE,
    OBSERVE_LANE,
    ControlSignal,
    FailPolicy,
    HookLane,
)


@dataclass(frozen=True)
class HookPointSpec:
    """Static metadata for one insertion point.

    The observe lane is always fail-open: errors and timeouts are logged and
    never block the turn. Only the modify lane carries an explicit fail policy.
    """

    name: str
    payload_type: Type[HookPayload]
    fail_policy_modify: FailPolicy | None
    allowed_control_signals: frozenset[ControlSignal]
    default_timeout_observe: int = DEFAULT_OBSERVE_TIMEOUT_MS
    default_timeout_modify: int = DEFAULT_MODIFY_TIMEOUT_MS

    @property
    def observe_decorator(self) -> str:
        return observe_decorator_name(self.name)

    @property
    def modify_decorator(self) -> str | None:
        return modify_decorator_name(self.name)


HOOK_POINT_SPECS: dict[str, HookPointSpec] = {
    POINT_TURN_STARTED: HookPointSpec(
        name=POINT_TURN_STARTED,
        payload_type=TurnStartedPayload,
        fail_policy_modify=None,
        allowed_control_signals=frozenset(),
    ),
    POINT_TURN_FINISHED: HookPointSpec(
        name=POINT_TURN_FINISHED,
        payload_type=TurnFinishedPayload,
        fail_policy_modify=None,
        allowed_control_signals=frozenset(),
    ),
    POINT_INCOMING_MESSAGE: HookPointSpec(
        name=POINT_INCOMING_MESSAGE,
        payload_type=IncomingMessagePayload,
        fail_policy_modify=FAIL_CLOSED,
        allowed_control_signals=frozenset({HookRejection}),
    ),
    POINT_MODEL_REQUEST: HookPointSpec(
        name=POINT_MODEL_REQUEST,
        payload_type=ModelRequestPayload,
        fail_policy_modify=FAIL_CLOSED,
        allowed_control_signals=frozenset(),
    ),
    POINT_MODEL_RESPONSE: HookPointSpec(
        name=POINT_MODEL_RESPONSE,
        payload_type=ModelResponsePayload,
        fail_policy_modify=FAIL_OPEN,
        allowed_control_signals=frozenset({RetryModel}),
    ),
    POINT_TOOL_CALL: HookPointSpec(
        name=POINT_TOOL_CALL,
        payload_type=ToolCallPayload,
        fail_policy_modify=FAIL_CLOSED,
        allowed_control_signals=frozenset({RetryModel}),
    ),
    POINT_TOOL_RESULT: HookPointSpec(
        name=POINT_TOOL_RESULT,
        payload_type=ToolResultPayload,
        fail_policy_modify=FAIL_OPEN,
        allowed_control_signals=frozenset(),
    ),
    POINT_KNOWLEDGE_QUERY: HookPointSpec(
        name=POINT_KNOWLEDGE_QUERY,
        payload_type=KnowledgeQueryPayload,
        fail_policy_modify=FAIL_CLOSED,
        allowed_control_signals=frozenset(),
    ),
    POINT_KNOWLEDGE_RESULTS: HookPointSpec(
        name=POINT_KNOWLEDGE_RESULTS,
        payload_type=KnowledgeResultsPayload,
        fail_policy_modify=FAIL_OPEN,
        allowed_control_signals=frozenset(),
    ),
    POINT_OUTGOING_TEXT: HookPointSpec(
        name=POINT_OUTGOING_TEXT,
        payload_type=OutgoingTextPayload,
        fail_policy_modify=FAIL_OPEN,
        allowed_control_signals=frozenset({HookRejection}),
    ),
}


DECORATOR_TO_POINT: dict[str, tuple[str, HookLane]] = {}
for _point_name, _spec in HOOK_POINT_SPECS.items():
    DECORATOR_TO_POINT[_spec.observe_decorator] = (_point_name, OBSERVE_LANE)
    if _spec.modify_decorator is not None:
        DECORATOR_TO_POINT[_spec.modify_decorator] = (_point_name, MODIFY_LANE)


def spec_for_point(point: str) -> HookPointSpec:
    """Return metadata for *point*, raising ``KeyError`` when unknown."""
    return HOOK_POINT_SPECS[point]


def spec_for_decorator(decorator_name: str) -> tuple[HookPointSpec, HookLane]:
    """Resolve a public decorator name to its point spec and lane."""
    point_name, lane = DECORATOR_TO_POINT[decorator_name]
    return HOOK_POINT_SPECS[point_name], lane
